A.bfb=new B.e(2,u.gh,"","\ubc24\uc5d0 \ucee4\ud53c\ub97c \ub9c8\uc2dc\uba74 \uc7a0\uc744 \ubabb \uc790\uc694.","drink",A.d2j)
A.dGL=s(["will heat","would heat","heats"],t.s)
A.bsD=new B.e(3,"If you heat ice, it melts.","","\uc5bc\uc74c\uc744 \ub370\uc6b0\uba74 \ub179\uc544\uc694.","heat",A.dGL)
A.cxH=s(["will be sunny","are sunny","be sunny"],t.s)
A.bp3=new B.e(4,"If it is sunny, we eat lunch outside.","","\ub0a0\uc528\uac00 \ub9d1\uc73c\uba74 \uc6b0\ub9ac\ub294 \ubc16\uc5d0\uc11c \uc810\uc2ec\uc744 \uba39\uc5b4\uc694.","is sunny",A.cxH)
